// And groups predicates with the AND operator between them.
func And(predicates ...predicate.UserQuotaAdjustment) predicate.UserQuotaAdjustment {
	return predicate.UserQuotaAdjustment(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.UserQuotaAdjustment) predicate.UserQuotaAdjustment {
	return predicate.UserQuotaAdjustment(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.UserQuotaAdjustment) predicate.UserQuotaAdjustment {
	return predicate.UserQuotaAdjustment(sql.NotPredicates(p))
}
